package com.fuelnet.tools;
import java.io.*;import java.nio.file.*;import java.util.*;
/** Java port of test_dataset_creator.py. */
public class TestDatasetGenerator{
 public static void main(String[] a)throws Exception{Path p=Path.of(a.length>0?a[0]:"dataset/test_dataset.csv");Files.createDirectories(p.getParent());Random r=new Random(42);try(PrintWriter w=new PrintWriter(Files.newBufferedWriter(p))){w.println("vehicle_speed_kmh,engine_rpm,throttle_position_percent,engine_load_percent,maf_gs,intake_air_temp_c,acceleration_ms2,brake_pedal_status,gear_position,fuel_consumption_lph,driving_profile,consumption_category,efficiency_score");String[]cats={"Very Low","Low","Medium","High","Very High"};double[][] ranges={{60,75,1800,2400,25,38,.3,1.2},{65,85,2200,2800,35,50,.8,1.8},{70,95,2600,3500,45,65,1.2,2.2},{85,110,3500,4500,60,80,2,3},{100,140,4500,6000,75,95,2.5,4}};for(int c=0;c<5;c++)for(int i=0;i<10;i++){double[]z=ranges[c];double s=u(r,z[0],z[1]),rpm=u(r,z[2],z[3]),t=u(r,z[4],z[5]),ac=u(r,z[6],z[7]),load=u(r,40+c*10,55+c*10),maf=u(r,15+c*9,22+c*11),fuel=Math.max(1.5,Math.min(15,rpm*t*load/(60000-c*5000)));int g=c<2?5:r.nextInt(5)+2,score=(rpm<2500?2:0)+(t<40?2:0)+(s>=60&&s<=80?2:0)+(g>=5?1:0)+(ac<1.5?1:0)-(rpm>4000?3:0)-(t>70?3:0)-(s>100?2:0)-(ac>2.5?2:0)-(g<=2?1:0);String profile=t>70||ac>2.5||rpm>4000?"Aggressive":t<35&&ac<1&&rpm<2500?"Eco-Friendly":s<50&&g<=3?"City":s>90&&g>=5?"Highway":"Moderate";w.printf(Locale.US,"%.2f,%.0f,%.2f,%.2f,%.2f,%.2f,%.2f,%d,%d,%.2f,%s,%s,%d%n",s,rpm,t,load,maf,u(r,25,45),ac,r.nextBoolean()?1:0,g,fuel,profile,cats[c],score);}}}
 static double u(Random r,double a,double b){return a+r.nextDouble()*(b-a);}
}
